def count_coprime_pairs(x0: int, y0: int) -> int:
    count = 0
    for a in range(1, y0 // x0 + 1):
        if y0 % (a * x0) == 0:
            b = y0 // (a * x0)
            if a == b:
                count += 1
            elif math.gcd(a, b) == 1:
                count += 2
    return count

